(171, '_site_transient_wp_plugin_dependencies_plugin_data', 'a:1:{s:14:\"contact-form-7\";a:35:{s:4:\"name\";s:14:\"Contact Form 7\";s:4:\"slug\";s:14:\"contact-form-7\";s:7:\"version\";s:5:\"6.1.7\";s:6:\"author\";s:78:\"<a href=\"https://profiles.wordpress.org/rocklobsterinc/\">Rock Lobster Inc.</a>\";s:14:\"author_profile\";s:46:\"https://profiles.wordpress.org/rocklobsterinc/\";s:12:\"contributors\";a:2:{s:14:\"rocklobsterinc\";a:3:{s:7:\"profile\";s:46:\"https://profiles.wordpress.org/rocklobsterinc/\";s:6:\"avatar\";s:120:\"https://secure.gravatar.com/avatar/4aa558df1c07e327536d8d0adad6d00fcdca0484c51adf0b867a2aa5ee054bbc?s=96&d=monsterid&r=g\";s:12:\"display_name\";s:17:\"Rock Lobster Inc.\";}s:12:\"takayukister\";a:3:{s:7:\"profile\";s:44:\"https://profiles.wordpress.org/takayukister/\";s:6:\"avatar\";s:120:\"https://secure.gravatar.com/avatar/538487024e649d43dea84ff38d14582d03119e3e7aaaca3b7692443335999133?s=96&d=monsterid&r=g\";s:12:\"display_name\";s:16:\"Takayuki Miyoshi\";}}s:8:\"requires\";s:3:\"6.7\";s:6:\"tested\";s:3:\"7.1\";s:12:\"requires_php\";s:3:\"7.4\";s:16:\"requires_plugins\";a:0:{}s:6:\"rating\";i:80;s:7:\"ratings\";a:5:{i:5;i:1472;i:4;i:156;i:3;i:79;i:2;i:68;i:1;i:404;}s:11:\"num_ratings\";i:2179;s:11:\"support_url\";s:52:\"https://wordpress.org/support/plugin/contact-form-7/\";s:15:\"support_threads\";i:45;s:24:\"support_threads_resolved\";i:26;s:15:\"active_installs\";i:10000000;s:12:\"last_updated\";s:21:\"2026-08-17 4:10am GMT\";s:5:\"added\";s:10:\"2007-08-02\";s:8:\"homepage\";s:25:\"https://contactform7.com/\";s:8:\"sections\";a:6:{s:11:\"description\";s:2525:\"<p>Contact Form 7 is a plugin designed to be a practical tool for all WordPress users who embrace the philosophy of free and open source software. It employs sophisticatedly modularized architecture and its original <a href=\"https://contactform7.com/schema-woven-validation/\" rel=\"nofollow ugc\">Schema-Woven Validation</a> technology.</p>\n<h4>Docs and support</h4>\n<p>You can find <a href=\"https://contactform7.com/docs/\" rel=\"nofollow ugc\">docs</a>, <a href=\"https://contactform7.com/faq/\" rel=\"nofollow ugc\">FAQ</a> and more detailed information about Contact Form 7 on <a href=\"https://contactform7.com/\" rel=\"nofollow ugc\">contactform7.com</a>. When you cannot find the answer to your question on the FAQ or in any of the documentation, check the <a href=\"https://wordpress.org/support/plugin/contact-form-7/\" rel=\"ugc\">support forum</a> on WordPress.org. If you cannot locate any topics that pertain to your particular issue, post a new topic for it.</p>\n<h4>Contact Form 7 needs your support</h4>\n<p>It is hard to continue to maintain this plugin without support from users like you. There are several ways for you to <a href=\"https://contactform7.com/contributing/\" rel=\"nofollow ugc\">contribute to the project</a>: testing, coding, translating it into your local languages, helping other users, financial donations, etc, etc. We equally welcome you regardless of the way you contribute.</p>\n<h4>Privacy notices</h4>\n<p>With the default configuration, this plugin, in itself, does not:</p>\n<ul>\n<li>track users by stealth;</li>\n<li>write any user personal data to the database;</li>\n<li>send any data to external servers;</li>\n<li>use cookies.</li>\n</ul>\n<p>If you activate certain features in this plugin, the contact form submitter&#8217;s personal data, including their IP address, may be sent to the service provider. Thus, confirming the provider&#8217;s privacy policy is recommended. These features include:</p>\n<ul>\n<li>reCAPTCHA (<a href=\"https://policies.google.com/?hl=en\" rel=\"nofollow ugc\">Google</a>)</li>\n<li>Akismet (<a href=\"https://automattic.com/privacy/\" rel=\"nofollow ugc\">Automattic</a>)</li>\n<li><a href=\"https://www.constantcontact.com/legal/privacy-center\" rel=\"nofollow ugc\">Constant Contact</a></li>\n<li><a href=\"https://www.brevo.com/legal/privacypolicy/\" rel=\"nofollow ugc\">Brevo</a></li>\n<li><a href=\"https://stripe.com/privacy\" rel=\"nofollow ugc\">Stripe</a></li>\n<li>Turnstile (<a href=\"https://www.cloudflare.com/turnstile-privacy-policy/\" rel=\"nofollow ugc\">Cloudflare</a>)</li>\n</ul>\n\";s:12:\"installation\";s:458:\"<ol>\n<li>Upload the entire <code>contact-form-7</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the <strong>Plugins</strong> screen (<strong>Plugins &gt; Installed Plugins</strong>).</li>\n</ol>\n<p>You will find <strong>Contact</strong> menu in your WordPress admin screen.</p>\n<p>For basic usage, have a look at the <a href=\"https://contactform7.com/\" rel=\"nofollow ugc\">plugin&#8217;s website</a>.</p>\n\";s:3:\"faq\";s:450:\"<p>Do you have questions or issues with Contact Form 7? Use these support channels appropriately.</p>\n<ol>\n<li><a href=\"https://contactform7.com/docs/\" rel=\"nofollow ugc\">Docs</a></li>\n<li><a href=\"https://contactform7.com/faq/\" rel=\"nofollow ugc\">FAQs</a></li>\n<li><a href=\"https://wordpress.org/support/plugin/contact-form-7/\" rel=\"ugc\">Support forum</a></li>\n</ol>\n<p><a href=\"https://contactform7.com/support/\" rel=\"nofollow ugc\">Support</a></p>\n\";s:9:\"changelog\";s:2206:\"<p>For more information, see <a href=\"https://contactform7.com/category/releases/\" rel=\"nofollow ugc\">Releases</a>.</p>\n<h4>6.1.7</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-617/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-617/</a></p>\n<h4>6.1.6</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-616/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-616/</a></p>\n<h4>6.1.5</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-615/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-615/</a></p>\n<h4>6.1.4</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-614/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-614/</a></p>\n<h4>6.1.3</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-613/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-613/</a></p>\n<h4>6.1.2</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-612/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-612/</a></p>\n<h4>6.1.1</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-611/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-611/</a></p>\n<h4>6.1</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-61/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-61/</a></p>\n<h4>6.0.5</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-605/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-605/</a></p>\n<h4>6.0.4</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-604/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-604/</a></p>\n<h4>6.0.3</h4>\n<ul>\n<li>Updates the copyright year to 2025.</li>\n<li>Updates the &#8220;Contact Form 7 needs your support&#8221; message content.</li>\n<li>Updates the Constant Contact deprecation warning.</li>\n</ul>\n<h4>6.0.2</h4>\n<ul>\n<li>Removes unnecessary type declaration from nullable arguments to avoid deprecation warnings in PHP 8.4.</li>\n</ul>\n<h4>6.0.1</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-601/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-601/</a></p>\n<h4>6.0</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-60/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-60/</a></p>\n\";s:11:\"screenshots\";s:225:\"<ol><li><a href=\"https://ps.w.org/contact-form-7/assets/screenshot-1.png?rev=1176454\"><img src=\"https://ps.w.org/contact-form-7/assets/screenshot-1.png?rev=1176454\" alt=\"screenshot-1.png\"></a><p>screenshot-1.png</p></li></ol>\";s:7:\"reviews\";s:16582:\"<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Problems and old fashion UI</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"3 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"3\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/echoalpha/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/bd3e7bc7649fe61308dbf6f6282f94a5bc4660fdea6a12bc9b38cd04f6463b42?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/bd3e7bc7649fe61308dbf6f6282f94a5bc4660fdea6a12bc9b38cd04f6463b42?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/echoalpha/\" class=\"reviewer-name\">echoalpha</a> on <span class=\"review-date\">August 30, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>I used CF7 for many many years and thank you for this But without a reason all forms stopped working. SMTP test email was ok, but no form was sending. Trying to remove captcha and make a form as simple but without success. I switched to another plugin and it\'s working normal. I rate it with 3 stars for all these years together !</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Best, Simple, Easy To use Plugin</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/samwilliam420/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/6d6a3b2c2234931eaacdbc9509d3bf315a16408288ab4ab3f8df61073a936d18?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/6d6a3b2c2234931eaacdbc9509d3bf315a16408288ab4ab3f8df61073a936d18?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/samwilliam420/\" class=\"reviewer-name\">samwilliam420</a> on <span class=\"review-date\">August 24, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>This is the best easy to use plugin for any kind of form set up. I have use CF7 Plugin on each and every clients sites.  </p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">A Plugin I’ve Trusted Throughout My Career</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/jitendradamor/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/c8c481eeb87f7a1451163c05f60537d0172d09b471e03080d05fdf1c392e55bc?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/c8c481eeb87f7a1451163c05f60537d0172d09b471e03080d05fdf1c392e55bc?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/jitendradamor/\" class=\"reviewer-name\">Jitendra Damor <small>(jitendradamor)</small></a> on <span class=\"review-date\">August 14, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Since the beginning of my career, Contact Form 7 has been one of the plugins I’ve used the most. Over the years, I’ve worked on many different websites, and it has consistently been a reliable solution for creating contact forms. What I appreciate most is its simplicity—it does the job without unnecessary complexity.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Even today, with so many alternatives available, I still find Contact Form 7 useful for projects that need a straightforward and dependable contact form. It’s flexible enough to be customized when needed and has remained a valuable tool in my WordPress development workflow for years.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Simple, Reliable Contact Forms</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/bowadviceluke/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/b2d3a69932b2eb742a788c482ac3594e6ca586bebfb12885fccc8adc3c69df5b?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/b2d3a69932b2eb742a788c482ac3594e6ca586bebfb12885fccc8adc3c69df5b?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/bowadviceluke/\" class=\"reviewer-name\">bowadviceluke</a> on <span class=\"review-date\">August 5, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Still one of those plugins I install on almost every site. It’s simple, doesn’t try to do too much, and just works. Not the prettiest interface, but once it’s set up I never really have to think about it again.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Simple But Most Useful</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/mehrazmorshed/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/eb5de3db5bfc8ef5845b4173265bf3d079f460fb99c9e346380b04d07bea8f05?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/eb5de3db5bfc8ef5845b4173265bf3d079f460fb99c9e346380b04d07bea8f05?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/mehrazmorshed/\" class=\"reviewer-name\">Mehraz Morshed <small>(mehrazmorshed)</small></a> on <span class=\"review-date\">July 27, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>I have known this plugin since I first started with WordPress and have used it for a long time. It is the simplest but most useful form plugin. Does exactly what it should, no extra clutter. Thanks to Takayuki Miyoshi.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Easy to set-up formular plugin</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/huygens-25/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/36ea9fa7ad9adb3e3872134e51ae2089b9e1237df346dfcbc7a21b2799e6aef4?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/36ea9fa7ad9adb3e3872134e51ae2089b9e1237df346dfcbc7a21b2799e6aef4?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/huygens-25/\" class=\"reviewer-name\">J-C Berthon <small>(huygens-25)</small></a> on <span class=\"review-date\">July 22, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>I really enjoyed that plugin. I needed last year to build a contact-us form for a WordPress website. I installed that plugin, and a few minutes later I add the contact form up and running, and it was just a matter of some more minutes (ok perhaps an hour, because I like reading documentation and testing ;-) ) so I add customised it to me liking.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Great plugin, does what it\'s supposed to do, and does it well and easy.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">best cf7</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/zuzo/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/b00e2d4f0a82270275d522957fbb3c3d095583d590d391abafc952bd773adad2?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/b00e2d4f0a82270275d522957fbb3c3d095583d590d391abafc952bd773adad2?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/zuzo/\" class=\"reviewer-name\">zuzo</a> on <span class=\"review-date\">July 5, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>very nice</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Handles Multiple Forms Well</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/garvin89/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/40bb3140f088e7a5df31fbbfaf953a58698492941ef330b60f617aea292d1c2a?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/40bb3140f088e7a5df31fbbfaf953a58698492941ef330b60f617aea292d1c2a?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/garvin89/\" class=\"reviewer-name\">garvin89</a> on <span class=\"review-date\">June 1, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>been running 3 diff forms on my site w this inquiry, booking &amp; feedback. all working fine w no conflicts. shortcode system is a bit old school bt once u get it, its actually flexible. happy w it overall</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Old School But Works</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/alenaalan/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/5774e9237df2d682251b5bb68ce3c0d0e676757b184baaf77ae287f7d8fd4122?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/5774e9237df2d682251b5bb68ce3c0d0e676757b184baaf77ae287f7d8fd4122?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/alenaalan/\" class=\"reviewer-name\">alenaalan</a> on <span class=\"review-date\">May 25, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Looks outdated ngl bt does exactly wht u need. Set up a working form in like 5 mins. Had 2 install a sep captcha plugin 4 spam tho. Still using it on every client site I build lol</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Just Use It</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/kaiasteffen/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/304cc2390b36443047cac9642cc98dfdcca9085ae8438af88f637647a1e4e564?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/304cc2390b36443047cac9642cc98dfdcca9085ae8438af88f637647a1e4e564?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/kaiasteffen/\" class=\"reviewer-name\">kaiasteffen</a> on <span class=\"review-date\">May 18, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>y r u even reading this lol just install it. free, lightweight &amp; gets the job done. my contact page has been running smooth 4 months w zero problems</p>\n<!-- /wp:paragraph --></div>\n</div>\n\";}s:17:\"short_description\";s:54:\"Just another contact form plugin. Simple but flexible.\";s:13:\"download_link\";s:63:\"https://downloads.wordpress.org/plugin/contact-form-7.6.1.7.zip\";s:14:\"upgrade_notice\";a:0:{}s:11:\"screenshots\";a:1:{i:1;a:2:{s:3:\"src\";s:67:\"https://ps.w.org/contact-form-7/assets/screenshot-1.png?rev=1176454\";s:7:\"caption\";s:16:\"screenshot-1.png\";}}s:4:\"tags\";a:2:{s:12:\"contact-form\";s:12:\"contact form\";s:23:\"schema-woven-validation\";s:23:\"schema-woven validation\";}s:8:\"versions\";a:204:{s:3:\"1.1\";s:61:\"https://downloads.wordpress.org/plugin/contact-form-7.1.1.zip\";s:4:\"1.10\";s:62:\"https://downloads.wordpress.org/plugin/contact-form-7.1.10.zip\";s:8:\"1.10.0.1\";s:66:\"https://downloads.wordpress.org/plugin/contact-form-7.1.10.0.1.zip\";s:6:\"1.10.1\";s:64:\"https: