(137, 66, '_form', '<div class=\"ma-form__row\">\n	<label class=\"ma-form__field\">\n		<span class=\"ma-form__label\">Name</span>\n		[text* your-name placeholder \"First name (or initials)\"]\n	</label>\n	<label class=\"ma-form__field\">\n		<span class=\"ma-form__label\">Email</span>\n		[email* your-email placeholder \"you@example.com\"]\n	</label>\n</div>\n<label class=\"ma-form__field\">\n	<span class=\"ma-form__label\">Subject</span>\n	[text your-subject placeholder \"How can we help?\"]\n</label>\n<label class=\"ma-form__field ma-form__field--message\">\n	<span class=\"ma-form__label\">Message</span>\n	[textarea* your-message rows:6 placeholder \"Tell us a little about what is going on. There is no wrong way to start.\"]\n</label>\n[submit class:ma-form__submit \"Send message\"]'),
(138, 66, '_mail', 'a:8:{s:7:\"subject\";s:27:\"[MA Toronto] [your-subject]\";s:6:\"sender\";s:32:\"MA Toronto <wordpress@localhost>\";s:9:\"recipient\";s:18:\"info@matoronto.org\";s:4:\"body\";s:139:\"From: [your-name] <[your-email]>\nSubject: [your-subject]\n\n[your-message]\n\n-- \nSent from the contact form on http://localhost:8888/matoronto\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";i:0;s:13:\"exclude_blank\";i:0;}'),
