INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2025-10-30 18:40:51', '2025-10-30 22:40:51', '<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->', 'Hello world!', '', 'publish', 'open', 'open', '', 'hello-world', '', '', '2025-10-30 18:40:51', '2025-10-30 22:40:51', '', 0, 'http://localhost:8888/matoronto/?p=1', 0, 'post', '', 1),
(3, 1, '2025-10-30 18:40:51', '2025-10-30 22:40:51', '<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost:8888/matoronto.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n', 'Privacy Policy', '', 'draft', 'closed', 'open', '', 'privacy-policy', '', '', '2025-10-30 18:40:51', '2025-10-30 22:40:51', '', 0, 'http://localhost:8888/matoronto/?page_id=3', 0, 'page', '', 0),
(4, 0, '2025-10-30 18:40:52', '2025-10-30 22:40:52', '<!-- wp:page-list /-->', 'Navigation', '', 'publish', 'closed', 'closed', '', 'navigation', '', '', '2025-10-30 18:40:52', '2025-10-30 22:40:52', '', 0, 'http://localhost:8888/matoronto/2025/10/30/navigation/', 0, 'wp_navigation', '', 0),
(6, 1, '2025-10-30 19:00:11', '2025-10-30 23:00:11', '<label> Your name\n    [text* your-name autocomplete:name] </label>\n\n<label> Your email\n    [email* your-email autocomplete:email] </label>\n\n<label> Subject\n    [text* your-subject] </label>\n\n<label> Your message (optional)\n    [textarea your-message] </label>\n\n[submit \"Submit\"]\n[_site_title] \"[your-subject]\"\n[_site_title] <info@matoronto.org>\nFrom: [your-name] [your-email]\nSubject: [your-subject]\n\nMessage Body:\n[your-message]\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\n[_site_admin_email]\nReply-To: [your-email]\n\n0\n0\n\n[_site_title] \"[your-subject]\"\n[_site_title] <info@matoronto.org>\nMessage Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\n[your-email]\nReply-To: [_site_admin_email]\n\n0\n0\nThank you for your message. It has been sent.\nThere was an error trying to send your message. Please try again later.\nOne or more fields have an error. Please check and try again.\nThere was an error trying to send your message. Please try again later.\nYou must accept the terms and conditions before sending your message.\nPlease fill out this field.\nThis field has a too long input.\nThis field has a too short input.\nThere was an unknown error uploading the file.\nYou are not allowed to upload files of this type.\nThe uploaded file is too large.\nThere was an error uploading the file.', 'Contact form 1', '', 'publish', 'closed', 'closed', '', 'contact-form-1', '', '', '2025-10-30 19:00:11', '2025-10-30 23:00:11', '', 0, 'http://localhost:8888/matoronto/?post_type=wpcf7_contact_form&p=6', 0, 'wpcf7_contact_form', '', 0),
(7, 1, '2025-10-30 19:00:22', '2025-10-30 23:00:22', '{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }', 'Custom Styles', '', 'publish', 'closed', 'closed', '', 'wp-global-styles-blocksy', '', '', '2025-10-30 19:00:22', '2025-10-30 23:00:22', '', 0, 'http://localhost:8888/matoronto/2025/10/30/wp-global-styles-blocksy/', 0, 'wp_global_styles', '', 0),
(12, 2, '2025-10-31 19:27:56', '2025-10-31 23:27:56', '<!-- wp:paragraph -->\n<p>The practice of rigorous honesty, of opening our hearts and minds, and the willingness to go to any lengths to have a spiritual awakening are essential to our recovery. Our old ideas and ways of life no longer work for us. Our suffering shows us that we need to let go absolutely. We surrender ourselves to a Power greater than ourselves. Here are the steps we take which are suggested for recovery:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We admitted we were powerless over marijuana, that our lives had become unmanageable.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Came to believe that a Power greater than ourselves could restore us to sanity.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made a decision to turn our will and our lives over to the care of God, as we understood God.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made a searching and fearless moral inventory of ourselves.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Admitted to God, to ourselves, and to another human being the exact nature of our wrongs.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Were entirely ready to have God remove all these defects of character.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Humbly asked God to remove our shortcomings.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made a list of all persons we had harmed, and became willing to make amends to them all.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made direct amends to such people wherever possible, except when to do so would injure them or others.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Continued to take personal inventory and when we were wrong, promptly admitted it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Sought through prayer and meditation to improve our conscious contact with God, as we understood God, praying only for knowledge of God’s will for us and the power to carry that out.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Having had a spiritual awakening as the result of these steps, we tried to carry this message to marijuana addicts and to practice these principles in all our affairs.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Do not be discouraged; none of us are saints. Our program is not easy, but it is simple. We strive for progress, not perfection. Our experiences, before and after we entered recovery, teach us three important ideas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>That we are marijuana addicts and cannot manage our own lives;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>That probably no human power can relieve our addiction;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>And that our Higher Power can and will if sought.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'The Twelve Steps', '', 'publish', 'closed', 'closed', '', 'the-twelve-steps', '', '', '2025-11-04 13:57:31', '2025-11-04 18:57:31', '', 14, 'http://localhost:8888/matoronto/?page_id=12', 0, 'page', '', 0),
(13, 1, '2025-10-31 19:27:56', '2025-10-31 23:27:56', '<!-- wp:paragraph -->\n<p>The practice of rigorous honesty, of opening our hearts and minds, and the willingness to go to any lengths to have a spiritual awakening are essential to our recovery. Our old ideas and ways of life no longer work for us. Our suffering shows us that we need to let go absolutely. We surrender ourselves to a Power greater than ourselves. Here are the steps we take which are suggested for recovery:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We admitted we were powerless over marijuana, that our lives had become unmanageable.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Came to believe that a Power greater than ourselves could restore us to sanity.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made a decision to turn our will and our lives over to the care of God, as we understood God.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made a searching and fearless moral inventory of ourselves.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Admitted to God, to ourselves, and to another human being the exact nature of our wrongs.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Were entirely ready to have God remove all these defects of character.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Humbly asked God to remove our shortcomings.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made a list of all persons we had harmed, and became willing to make amends to them all.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Made direct amends to such people wherever possible, except when to do so would injure them or others.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Continued to take personal inventory and when we were wrong, promptly admitted it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Sought through prayer and meditation to improve our conscious contact with God, as we understood God, praying only for knowledge of God’s will for us and the power to carry that out.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Having had a spiritual awakening as the result of these steps, we tried to carry this message to marijuana addicts and to practice these principles in all our affairs.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Do not be discouraged; none of us are saints. Our program is not easy, but it is simple. We strive for progress, not perfection. Our experiences, before and after we entered recovery, teach us three important ideas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>That we are marijuana addicts and cannot manage our own lives;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>That probably no human power can relieve our addiction;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>And that our Higher Power can and will if sought.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'The Twelve Steps', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2025-10-31 19:27:56', '2025-10-31 23:27:56', '', 12, 'http://localhost:8888/matoronto/?p=13', 0, 'revision', '', 0),
(14, 2, '2025-10-31 19:30:01', '2025-10-31 23:30:01', '', 'How It Works', '', 'publish', 'closed', 'closed', '', 'how-it-works', '', '', '2026-08-09 18:17:49', '2026-08-09 22:17:49', '', 0, 'http://localhost:8888/matoronto/?page_id=14', 0, 'page', '', 0),
(15, 1, '2025-10-31 19:29:46', '2025-10-31 23:29:46', '', 'How It Works', '', 'inherit', 'closed', 'closed', '', '14-revision-v1', '', '', '2025-10-31 19:29:46', '2025-10-31 23:29:46', '', 14, 'http://localhost:8888/matoronto/?p=15', 0, 'revision', '', 0),
(16, 2, '2025-11-04 13:21:53', '2025-11-04 18:21:53', '<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Our common welfare should come first; personal recovery depends upon M.A. unity.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>For our group purpose there is but one ultimate authority, a loving God whose expression may come through in our group conscience. Our leaders are but trusted servants; they do not govern.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The only requirement for membership is a desire to stop using marijuana.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Each group has but one primary purpose, to carry its message to the marijuana addict who still suffers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Each group should be autonomous except in matters affecting other groups or M.A. as a whole.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>M.A. groups ought never endorse, finance, or lend the M.A. name to any related facility or outside enterprise, lest problems of money, property, and prestige divert us from our primary purpose.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Every M.A. group ought to be fully self-supporting, declining outside contributions.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Marijuana Anonymous should remain forever nonprofessional, but our service centers may employ special workers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>M.A., as such, ought never be organized, but we may create service boards or committees directly responsible to those they serve.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Marijuana Anonymous has no opinion on outside issues; hence the M.A. name ought never be drawn into public controversy.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Our public relations policy is based upon attraction rather than promotion; we need always maintain personal anonymity at the level of press, radio, TV, film, and other public media. We need guard with special care the anonymity of all fellow M.A. members.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Anonymity is the spiritual foundation of all our traditions, ever reminding us to place principles before personalities.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'The Twelve Traditions', '', 'publish', 'closed', 'closed', '', 'the-twelve-traditions', '', '', '2025-11-04 13:58:16', '2025-11-04 18:58:16', '', 14, 'http://localhost:8888/matoronto/?page_id=16', 0, 'page', '', 0),
(17, 1, '2025-11-04 13:21:53', '2025-11-04 18:21:53', '<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Our common welfare should come first; personal recovery depends upon M.A. unity.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>For our group purpose there is but one ultimate authority, a loving God whose expression may come through in our group conscience. Our leaders are but trusted servants; they do not govern.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The only requirement for membership is a desire to stop using marijuana.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Each group has but one primary purpose, to carry its message to the marijuana addict who still suffers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Each group should be autonomous except in matters affecting other groups or M.A. as a whole.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>M.A. groups ought never endorse, finance, or lend the M.A. name to any related facility or outside enterprise, lest problems of money, property, and prestige divert us from our primary purpose.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Every M.A. group ought to be fully self-supporting, declining outside contributions.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Marijuana Anonymous should remain forever nonprofessional, but our service centers may employ special workers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>M.A., as such, ought never be organized, but we may create service boards or committees directly responsible to those they serve.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Marijuana Anonymous has no opinion on outside issues; hence the M.A. name ought never be drawn into public controversy.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Our public relations policy is based upon attraction rather than promotion; we need always maintain personal anonymity at the level of press, radio, TV, film, and other public media. We need guard with special care the anonymity of all fellow M.A. members.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Anonymity is the spiritual foundation of all our traditions, ever reminding us to place principles before personalities.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'The Twelve Traditions', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2025-11-04 13:21:53', '2025-11-04 18:21:53', '', 16, 'http://localhost:8888/matoronto/?p=17', 0, 'revision', '', 0),
(18, 2, '2025-11-04 13:24:54', '2025-11-04 18:24:54', '<!-- wp:paragraph -->\n<p>The following questions may help you determine whether marijuana is a problem in your life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Has using marijuana stopped being fun?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you ever get high alone?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Is it hard for you to imagine a life without marijuana?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you find that your friends are determined by your marijuana use?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you use marijuana to avoid dealing with your problems or to cope with your feelings?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Has your marijuana use led to financial difficulties and/or legal consequences?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Does your marijuana use let you live in a privately defined world?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Have you ever failed to keep promises you made about cutting down or controlling your use of marijuana?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Has your use of marijuana caused problems with your health, memory, concentration, or motivation?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>When your stash is nearly empty, do you feel anxious or worried about how to get more?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you plan your life around your marijuana use?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Have friends or relatives ever complained that your using is damaging your relationship with them?</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>If you answered yes to any of the above questions, you may have a problem with marijuana.</p>\n<!-- /wp:paragraph -->', 'The Twelve Questions', '', 'publish', 'closed', 'closed', '', 'the-twelve-questions', '', '', '2025-11-04 13:58:41', '2025-11-04 18:58:41', '', 14, 'http://localhost:8888/matoronto/?page_id=18', 0, 'page', '', 0),
(19, 1, '2025-11-04 13:24:54', '2025-11-04 18:24:54', '<!-- wp:paragraph -->\n<p>The following questions may help you determine whether marijuana is a problem in your life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Has using marijuana stopped being fun?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you ever get high alone?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Is it hard for you to imagine a life without marijuana?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you find that your friends are determined by your marijuana use?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you use marijuana to avoid dealing with your problems or to cope with your feelings?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Has your marijuana use led to financial difficulties and/or legal consequences?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Does your marijuana use let you live in a privately defined world?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Have you ever failed to keep promises you made about cutting down or controlling your use of marijuana?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Has your use of marijuana caused problems with your health, memory, concentration, or motivation?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>When your stash is nearly empty, do you feel anxious or worried about how to get more?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Do you plan your life around your marijuana use?</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Have friends or relatives ever complained that your using is damaging your relationship with them?</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>If you answered yes to any of the above questions, you may have a problem with marijuana.</p>\n<!-- /wp:paragraph -->', 'The Twelve Questions', '', 'inherit', 'closed', 'closed', '', '18-revision-v1', '', '', '2025-11-04 13:24:54', '2025-11-04 18:24:54', '', 18, 'http://localhost:8888/matoronto/?p=19', 0, 'revision', '', 0),
(20, 2, '2025-11-04 13:28:19', '2025-11-04 18:28:19', '<!-- wp:paragraph -->\n<p>As stated in our third tradition, the only requirement for membership in Marijuana Anonymous is a desire to stop using marijuana. There is no mention of any other drugs or alcohol. This is to adhere to the “singleness of purpose” concept, however, many of us have found that the only way that we can keep our sobriety is to also abstain from alcohol and all other mind-altering substances (unless those other substances are taken as prescribed by a healthcare provider). When we give up the drug of our choice, a void is created. The initial struggle to abstain from marijuana use often leaves us vulnerable. To fill this void, we may start to use, or increase the use of, other substances such as alcohol, cocaine, pills, or other self-prescribed drugs. Although we may not now be addicted to these substances, their use can lower our inhibitions, leaving us open to repeating old patterns of thinking and behaving that can lead back to marijuana use. The fact that we became addicted to marijuana reflects a tendency towards behavior that may lead to cross addiction or substitution addiction to these substances.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>To reiterate, the only requirement for membership is a desire to stop using marijuana. It is important, however, to recognize the potential to create another problem as we strive to recover from this one.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph -->\n<p><em>Excerpt from the&nbsp;<a href=\"https://marijuana-anonymous.org/pamphlets/dangers-of-cross-addiction/\">Dangers of Cross Addiction pamphlet</a>,&nbsp;reprinted with permission of MA World Services.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Dangers of Cross Addiction', '', 'publish', 'closed', 'closed', '', 'dangers-of-cross-addiction', '', '', '2025-11-04 13:59:35', '2025-11-04 18:59:35', '', 14, 'http://localhost:8888/matoronto/?page_id=20', 0, 'page', '', 0),
(21, 1, '2025-11-04 13:28:19', '2025-11-04 18:28:19', '<!-- wp:paragraph -->\n<p>As stated in our third tradition, the only requirement for membership in Marijuana Anonymous is a desire to stop using marijuana. There is no mention of any other drugs or alcohol. This is to adhere to the “singleness of purpose” concept, however, many of us have found that the only way that we can keep our sobriety is to also abstain from alcohol and all other mind-altering substances (unless those other substances are taken as prescribed by a healthcare provider). When we give up the drug of our choice, a void is created. The initial struggle to abstain from marijuana use often leaves us vulnerable. To fill this void, we may start to use, or increase the use of, other substances such as alcohol, cocaine, pills, or other self-prescribed drugs. Although we may not now be addicted to these substances, their use can lower our inhibitions, leaving us open to repeating old patterns of thinking and behaving that can lead back to marijuana use. The fact that we became addicted to marijuana reflects a tendency towards behavior that may lead to cross addiction or substitution addiction to these substances.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>To reiterate, the only requirement for membership is a desire to stop using marijuana. It is important, however, to recognize the potential to create another problem as we strive to recover from this one.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph -->\n<p><em>Excerpt from the&nbsp;<a href=\"https://marijuana-anonymous.org/pamphlets/dangers-of-cross-addiction/\">Dangers of Cross Addiction pamphlet</a>,&nbsp;reprinted with permission of MA World Services.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Dangers of Cross Addiction', '', 'inherit', 'closed', 'closed', '', '20-revision-v1', '', '', '2025-11-04 13:28:19', '2025-11-04 18:28:19', '', 20, 'http://localhost:8888/matoronto/?p=21', 0, 'revision', '', 0),
(22, 2, '2025-11-04 13:30:09', '2025-11-04 18:30:09', '<!-- wp:paragraph -->\n<p>There are two days in every week&nbsp;<br>about which we should not worry,&nbsp;<br>Two days which should be kept free of fear and apprehension.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>One of these days is YESTERDAY,&nbsp;<br>With its mistakes and cares,&nbsp;<br>Its faults and blunders,&nbsp;<br>Its aches and pains.&nbsp;<br>YESTERDAY has passed forever beyond our control.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>All the money in the world cannot bring back YESTERDAY.<br>We cannot undo a single act we performed;&nbsp;<br>We cannot erase a single word we said.&nbsp;<br>YESTERDAY is gone.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The other day we should not worry about is TOMORROW<br>With its possible adversities, its burdens, its larger promise.<br>TOMORROW is also beyond our immediate control.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>TOMORROW, the sun will rise,&nbsp;<br>Either in splendor or behind a mask of clouds,&nbsp;<br>But it will rise.&nbsp;<br>Until it does, we have no stake in TOMORROW&nbsp;<br>For it is as yet unborn.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This leaves only one day – TODAY.&nbsp;<br>Any person can fight the battles of just one day.&nbsp;<br>It is only when you and I add the burdens of those two awful eternities<br>– YESTERDAY and TOMORROW –&nbsp;<br>That we break down.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>It is not the experience of TODAY that drives people mad.<br>It is remorse or bitterness for something which happened YESTERDAY<br>And the dread of what TOMORROW may bring.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Let us, therefore, live but ONE day at a time.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Author Unknown</strong></p>\n<!-- /wp:paragraph -->', 'Yesterday, Today and Tomorrow', '', 'publish', 'closed', 'closed', '', 'yesterday-today-and-tomorrow', '', '', '2025-11-04 14:00:42', '2025-11-04 19:00:42', '', 14, 'http://localhost:8888/matoronto/?page_id=22', 0, 'page', '', 0),
