(56, 0, '2026-09-06 14:49:16', '2026-09-06 18:49:16', '<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-hero is-style-hero-wash\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|100\",\"bottom\":\"var:preset|spacing|90\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull ma-hero is-style-hero-wash\" style=\"padding-top:var(--wp--preset--spacing--100);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--90);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"ma-hero__cols\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|90\",\"left\":\"var:preset|spacing|90\"}}}} -->\n	<div class=\"wp-block-columns are-vertically-aligned-center ma-hero__cols\">\n\n		<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"52.5%\"} -->\n		<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:52.5%\">\n\n			<!-- wp:paragraph {\"className\":\"is-style-eyebrow ma-hero__eyebrow\",\"textColor\":\"accent\",\"fontSize\":\"xx-small\"} -->\n			<p class=\"is-style-eyebrow ma-hero__eyebrow has-accent-color has-text-color has-xx-small-font-size\">A fellowship of recovery</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:heading {\"level\":1,\"className\":\"ma-hero__title\",\"fontSize\":\"display-lg\"} -->\n			<h1 class=\"wp-block-heading ma-hero__title has-display-lg-font-size\">You are no longer alone.</h1>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-hero__lede\",\"textColor\":\"body\",\"fontSize\":\"large\"} -->\n			<p class=\"ma-hero__lede has-body-color has-text-color has-large-font-size\">Marijuana Anonymous Toronto is a free peer-support fellowship for anyone with a desire to stop using marijuana. Meetings run every week — in person across the GTA and online.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:group {\"className\":\"ma-hero__actions\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"verticalAlignment\":\"center\"}} -->\n			<div class=\"wp-block-group ma-hero__actions\">\n				<!-- wp:buttons -->\n				<div class=\"wp-block-buttons\">\n					<!-- wp:button -->\n					<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost:8888/matoronto/meetings/\">Find a Meeting</a></div>\n					<!-- /wp:button -->\n				</div>\n				<!-- /wp:buttons -->\n\n				<!-- wp:paragraph {\"className\":\"is-style-underline-link ma-hero__secondary\",\"fontSize\":\"medium\"} -->\n				<p class=\"is-style-underline-link ma-hero__secondary has-medium-font-size\"><a href=\"http://localhost:8888/matoronto/the-twelve-questions/\">Am I an addict? Take the 12 Questions</a></p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:group -->\n\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"47.5%\"} -->\n		<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:47.5%\">\n			<!-- wp:image {\"className\":\"ma-hero__media\",\"style\":{\"border\":{\"radius\":\"var:custom|radius|lg\"},\"shadow\":\"var:preset|shadow|lg\"}} -->\n			<figure class=\"wp-block-image ma-hero__media\"><img src=\"http://localhost:8888/matoronto/wp-content/themes/ma-toronto/assets/images/hero-placeholder.svg\" alt=\"\" style=\"border-radius:var(--wp--custom--radius--lg);box-shadow:var(--wp--preset--shadow--lg)\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-pathways is-style-surface\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|90\",\"bottom\":\"var:preset|spacing|90\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull ma-pathways is-style-surface\" style=\"padding-top:var(--wp--preset--spacing--90);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--90);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:heading {\"level\":2,\"className\":\"screen-reader-text\"} -->\n	<h2 class=\"wp-block-heading screen-reader-text\">Explore MA Toronto</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:group {\"className\":\"ma-pathways__grid\",\"style\":{\"spacing\":{\"blockGap\":\"18px\"}},\"layout\":{\"type\":\"grid\",\"columnCount\":6}} -->\n	<div class=\"wp-block-group ma-pathways__grid\">\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/meetings/\">Meetings</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">All MA meetings in the Toronto area, in person and online.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">See schedule <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/the-twelve-steps/\">A Solution</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">How it works: the 12 Steps of recovery, founded by AA.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">How it works <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/our-stories/\">Our Stories</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">Members share what it was like — before and after recovery.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Read stories <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/faq/\">FAQ</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">You have questions. We have answers, from people who&#039;ve been there.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Get answers <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/literature/\">Literature</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">Life with Hope, pamphlets, and all official MA literature.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Browse <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/contact/\">Contact Us</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">Reach the Toronto fellowship directly. We are glad to hear from you.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Get in touch <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-about is-style-forest\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|100\",\"bottom\":\"var:preset|spacing|100\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull ma-about is-style-forest\" style=\"padding-top:var(--wp--preset--spacing--100);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--100);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:group {\"className\":\"ma-about__copy\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"820px\"}} -->\n	<div class=\"wp-block-group ma-about__copy\">\n\n		<!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"className\":\"ma-about__title\",\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-text-align-center ma-about__title has-xx-large-font-size\">A fellowship of people who share experience, strength, and hope.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"ma-about__body\",\"fontSize\":\"medium\"} -->\n		<p class=\"has-text-align-center ma-about__body has-medium-font-size\">The only requirement for membership is a desire to stop using marijuana. There are no dues or fees. MA is not affiliated with any religious or secular organization — our primary purpose is to stay free of marijuana and to help the marijuana addict who still suffers achieve the same freedom.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"ma-about__highlight\",\"textColor\":\"sand\",\"fontSize\":\"medium\"} -->\n		<p class=\"has-text-align-center ma-about__highlight has-sand-color has-text-color has-medium-font-size\"><strong>No one is excluded from MA — every age, background, identity, and walk of life is welcome.</strong></p>\n		<!-- /wp:paragraph -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"ma-stats\",\"style\":{\"spacing\":{\"blockGap\":\"120px\",\"margin\":{\"top\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\",\"verticalAlignment\":\"stretch\"}} -->\n	<div class=\"wp-block-group ma-stats\" style=\"margin-top:var(--wp--preset--spacing--80)\">\n\n		<!-- wp:group {\"className\":\"ma-stat\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-stat\">\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-stat ma-stat__figure\"} -->\n			<p class=\"has-text-align-center is-style-stat ma-stat__figure\">392+</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-eyebrow ma-stat__label\"} -->\n			<p class=\"has-text-align-center is-style-eyebrow ma-stat__label\">MA meetings worldwide</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:separator {\"className\":\"ma-stats__rule\"} -->\n		<hr class=\"wp-block-separator has-alpha-channel-opacity ma-stats__rule\"/>\n		<!-- /wp:separator -->\n\n		<!-- wp:group {\"className\":\"ma-stat\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-stat\">\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-stat ma-stat__figure\"} -->\n			<p class=\"has-text-align-center is-style-stat ma-stat__figure\">$366,218+</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-eyebrow ma-stat__label\"} -->\n			<p class=\"has-text-align-center is-style-eyebrow ma-stat__label\">Saved by our members</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-quote\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|100\",\"bottom\":\"var:preset|spacing|100\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"},\"blockGap\":\"var:preset|spacing|50\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"900px\"}} -->\n<div class=\"wp-block-group alignfull ma-quote\" style=\"padding-top:var(--wp--preset--spacing--100);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--100);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"className\":\"is-style-eyebrow ma-quote__label\",\"textColor\":\"accent\",\"fontSize\":\"xx-small\"} -->\n	<h2 class=\"wp-block-heading has-text-align-center is-style-eyebrow ma-quote__label has-accent-color has-text-color has-xx-small-font-size\">Quotes &amp; slogans</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:group {\"className\":\"ma-quote__track\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group ma-quote__track\">\n		<!-- wp:quote {\"className\":\"ma-quote__slide\"} -->\n		<blockquote class=\"wp-block-quote ma-quote__slide\">\n			<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"quote\"} -->\n			<p class=\"has-text-align-center has-quote-font-size\">One day at a time.</p>\n			<!-- /wp:paragraph -->\n		</blockquote>\n		<!-- /wp:quote -->\n		<!-- wp:quote {\"className\":\"ma-quote__slide\"} -->\n		<blockquote class=\"wp-block-quote ma-quote__slide\">\n			<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"quote\"} -->\n			<p class=\"has-text-align-center has-quote-font-size\">Keep it simple.</p>\n			<!-- /wp:paragraph -->\n		</blockquote>\n		<!-- /wp:quote -->\n		<!-- wp:quote {\"className\":\"ma-quote__slide\"} -->\n		<blockquote class=\"wp-block-quote ma-quote__slide\">\n			<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"quote\"} -->\n			<p class=\"has-text-align-center has-quote-font-size\">Progress, not perfection.</p>\n			<!-- /wp:paragraph -->\n		</blockquote>\n		<!-- /wp:quote -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '49-revision-v1', '', '', '2026-09-06 14:49:16', '2026-09-06 18:49:16', '', 49, 'http://localhost:8888/matoronto/?p=56', 0, 'revision', '', 0),
(57, 0, '2026-09-06 14:49:41', '2026-09-06 18:49:41', '<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-hero is-style-hero-wash\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|100\",\"bottom\":\"var:preset|spacing|90\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull ma-hero is-style-hero-wash\" style=\"padding-top:var(--wp--preset--spacing--100);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--90);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"ma-hero__cols\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|90\",\"left\":\"var:preset|spacing|90\"}}}} -->\n	<div class=\"wp-block-columns are-vertically-aligned-center ma-hero__cols\">\n\n		<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"52.5%\"} -->\n		<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:52.5%\">\n\n			<!-- wp:paragraph {\"className\":\"is-style-eyebrow ma-hero__eyebrow\",\"textColor\":\"accent\",\"fontSize\":\"xx-small\"} -->\n			<p class=\"is-style-eyebrow ma-hero__eyebrow has-accent-color has-text-color has-xx-small-font-size\">A fellowship of recovery</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:heading {\"level\":1,\"className\":\"ma-hero__title\",\"fontSize\":\"display-lg\"} -->\n			<h1 class=\"wp-block-heading ma-hero__title has-display-lg-font-size\">You are no longer alone.</h1>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-hero__lede\",\"textColor\":\"body\",\"fontSize\":\"large\"} -->\n			<p class=\"ma-hero__lede has-body-color has-text-color has-large-font-size\">Marijuana Anonymous Toronto is a free peer-support fellowship for anyone with a desire to stop using marijuana. Meetings run every week — in person across the GTA and online.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:group {\"className\":\"ma-hero__actions\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"verticalAlignment\":\"center\"}} -->\n			<div class=\"wp-block-group ma-hero__actions\">\n				<!-- wp:buttons -->\n				<div class=\"wp-block-buttons\">\n					<!-- wp:button -->\n					<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost:8888/matoronto/meetings/\">Find a Meeting</a></div>\n					<!-- /wp:button -->\n				</div>\n				<!-- /wp:buttons -->\n\n				<!-- wp:paragraph {\"className\":\"is-style-underline-link ma-hero__secondary\",\"fontSize\":\"medium\"} -->\n				<p class=\"is-style-underline-link ma-hero__secondary has-medium-font-size\"><a href=\"http://localhost:8888/matoronto/the-twelve-questions/\">Am I an addict? Take the 12 Questions</a></p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:group -->\n\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"47.5%\"} -->\n		<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:47.5%\">\n			<!-- wp:image {\"className\":\"ma-hero__media\",\"style\":{\"border\":{\"radius\":\"var:custom|radius|lg\"},\"shadow\":\"var:preset|shadow|lg\"}} -->\n			<figure class=\"wp-block-image has-custom-border ma-hero__media\"><img src=\"http://localhost:8888/matoronto/wp-content/themes/ma-toronto/assets/images/hero-placeholder.svg\" alt=\"\" style=\"border-radius:var(--wp--custom--radius--lg);box-shadow:var(--wp--preset--shadow--lg)\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-pathways is-style-surface\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|90\",\"bottom\":\"var:preset|spacing|90\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull ma-pathways is-style-surface\" style=\"padding-top:var(--wp--preset--spacing--90);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--90);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:heading {\"level\":2,\"className\":\"screen-reader-text\"} -->\n	<h2 class=\"wp-block-heading screen-reader-text\">Explore MA Toronto</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:group {\"className\":\"ma-pathways__grid\",\"style\":{\"spacing\":{\"blockGap\":\"18px\"}},\"layout\":{\"type\":\"grid\",\"columnCount\":6}} -->\n	<div class=\"wp-block-group ma-pathways__grid\">\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/meetings/\">Meetings</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">All MA meetings in the Toronto area, in person and online.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">See schedule <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/the-twelve-steps/\">A Solution</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">How it works: the 12 Steps of recovery, founded by AA.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">How it works <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/our-stories/\">Our Stories</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">Members share what it was like — before and after recovery.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Read stories <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/faq/\">FAQ</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">You have questions. We have answers, from people who&#039;ve been there.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Get answers <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/literature/\">Literature</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">Life with Hope, pamphlets, and all official MA literature.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Browse <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"ma-card is-style-card\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-card is-style-card\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-card__title has-large-font-size\"><a href=\"http://localhost:8888/matoronto/contact/\">Contact Us</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-card__desc has-muted-color has-text-color has-small-font-size\">Reach the Toronto fellowship directly. We are glad to hear from you.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-card__cta has-x-small-font-size\">Get in touch <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-about is-style-forest\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|100\",\"bottom\":\"var:preset|spacing|100\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull ma-about is-style-forest\" style=\"padding-top:var(--wp--preset--spacing--100);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--100);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:group {\"className\":\"ma-about__copy\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"820px\"}} -->\n	<div class=\"wp-block-group ma-about__copy\">\n\n		<!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"className\":\"ma-about__title\",\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-text-align-center ma-about__title has-xx-large-font-size\">A fellowship of people who share experience, strength, and hope.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"ma-about__body\",\"fontSize\":\"medium\"} -->\n		<p class=\"has-text-align-center ma-about__body has-medium-font-size\">The only requirement for membership is a desire to stop using marijuana. There are no dues or fees. MA is not affiliated with any religious or secular organization — our primary purpose is to stay free of marijuana and to help the marijuana addict who still suffers achieve the same freedom.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"ma-about__highlight\",\"textColor\":\"sand\",\"fontSize\":\"medium\"} -->\n		<p class=\"has-text-align-center ma-about__highlight has-sand-color has-text-color has-medium-font-size\"><strong>No one is excluded from MA — every age, background, identity, and walk of life is welcome.</strong></p>\n		<!-- /wp:paragraph -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"ma-stats\",\"style\":{\"spacing\":{\"blockGap\":\"120px\",\"margin\":{\"top\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\",\"verticalAlignment\":\"stretch\"}} -->\n	<div class=\"wp-block-group ma-stats\" style=\"margin-top:var(--wp--preset--spacing--80)\">\n\n		<!-- wp:group {\"className\":\"ma-stat\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-stat\">\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-stat ma-stat__figure\"} -->\n			<p class=\"has-text-align-center is-style-stat ma-stat__figure\">392+</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-eyebrow ma-stat__label\"} -->\n			<p class=\"has-text-align-center is-style-eyebrow ma-stat__label\">MA meetings worldwide</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:separator {\"className\":\"ma-stats__rule\"} -->\n		<hr class=\"wp-block-separator has-alpha-channel-opacity ma-stats__rule\"/>\n		<!-- /wp:separator -->\n\n		<!-- wp:group {\"className\":\"ma-stat\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-stat\">\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-stat ma-stat__figure\"} -->\n			<p class=\"has-text-align-center is-style-stat ma-stat__figure\">$366,218+</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"align\":\"center\",\"className\":\"is-style-eyebrow ma-stat__label\"} -->\n			<p class=\"has-text-align-center is-style-eyebrow ma-stat__label\">Saved by our members</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"templateLock\":\"contentOnly\",\"lock\":{\"move\":true,\"remove\":true},\"align\":\"full\",\"className\":\"ma-quote\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|100\",\"bottom\":\"var:preset|spacing|100\",\"left\":\"var:preset|spacing|80\",\"right\":\"var:preset|spacing|80\"},\"blockGap\":\"var:preset|spacing|50\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"900px\"}} -->\n<div class=\"wp-block-group alignfull ma-quote\" style=\"padding-top:var(--wp--preset--spacing--100);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--100);padding-left:var(--wp--preset--spacing--80)\">\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"className\":\"is-style-eyebrow ma-quote__label\",\"textColor\":\"accent\",\"fontSize\":\"xx-small\"} -->\n	<h2 class=\"wp-block-heading has-text-align-center is-style-eyebrow ma-quote__label has-accent-color has-text-color has-xx-small-font-size\">Quotes &amp; slogans</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:group {\"className\":\"ma-quote__track\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group ma-quote__track\">\n		<!-- wp:quote {\"className\":\"ma-quote__slide\"} -->\n		<blockquote class=\"wp-block-quote ma-quote__slide\">\n			<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"quote\"} -->\n			<p class=\"has-text-align-center has-quote-font-size\">One day at a time.</p>\n			<!-- /wp:paragraph -->\n		</blockquote>\n		<!-- /wp:quote -->\n		<!-- wp:quote {\"className\":\"ma-quote__slide\"} -->\n		<blockquote class=\"wp-block-quote ma-quote__slide\">\n			<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"quote\"} -->\n			<p class=\"has-text-align-center has-quote-font-size\">Keep it simple.</p>\n			<!-- /wp:paragraph -->\n		</blockquote>\n		<!-- /wp:quote -->\n		<!-- wp:quote {\"className\":\"ma-quote__slide\"} -->\n		<blockquote class=\"wp-block-quote ma-quote__slide\">\n			<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"quote\"} -->\n			<p class=\"has-text-align-center has-quote-font-size\">Progress, not perfection.</p>\n			<!-- /wp:paragraph -->\n		</blockquote>\n		<!-- /wp:quote -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '49-revision-v1', '', '', '2026-09-06 14:49:41', '2026-09-06 18:49:41', '', 49, 'http://localhost:8888/matoronto/?p=57', 0, 'revision', '', 0),
(58, 0, '2026-09-06 15:19:08', '2026-09-06 19:19:08', '<!-- wp:accordion {\"autoclose\":true,\"headingLevel\":3,\"className\":\"ma-faq\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\"}}} -->\n<div class=\"wp-block-accordion ma-faq\" role=\"group\">\n	<!-- wp:accordion-item {\"openByDefault\":true} -->\n	<div class=\"wp-block-accordion-item is-open\">\n		<!-- wp:accordion-heading -->\n		<h3 class=\"wp-block-accordion-heading has-icon has-icon-right\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">What is Marijuana Anonymous?</span><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\" role=\"region\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">MA is a fellowship of people who share their experience, strength, and hope with each other so they may solve their common problem and help others recover from marijuana addiction. We use the same Twelve Steps of recovery founded by Alcoholics Anonymous.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading -->\n		<h3 class=\"wp-block-accordion-heading has-icon has-icon-right\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">How much does it cost?</span><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\" role=\"region\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">Nothing. There are no dues or fees for membership. MA is entirely self-supporting through voluntary contributions from members — the 7th Tradition.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading -->\n		<h3 class=\"wp-block-accordion-heading has-icon has-icon-right\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">Do I have to speak or share personal details?</span><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\" role=\"region\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">No. You can come to a meeting and simply listen for as long as you like. Many people attend several meetings before sharing anything. Only your first name is ever needed — anonymity is a core principle.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading -->\n		<h3 class=\"wp-block-accordion-heading has-icon has-icon-right\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">How do I know if I am a marijuana addict?</span><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\" role=\"region\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">Only you can decide. Many members found it helpful to read The Twelve Questions — an honest self-inventory about how marijuana affects your life. If marijuana is causing problems and you cannot seem to stop, MA may be for you.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading -->\n		<h3 class=\"wp-block-accordion-heading has-icon has-icon-right\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">Is MA religious?</span><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\" role=\"region\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">No. MA is not affiliated with any religious or secular organization. The program refers to a higher power of your own understanding — that can be anything, including the group itself. Members hold every belief and none.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading -->\n		<h3 class=\"wp-block-accordion-heading has-icon has-icon-right\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">What happens at a meeting?</span><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\" role=\"region\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">Meetings usually open with a reading, followed by members sharing their experience on a topic or a Step. They typically last about an hour. In-person meetings are held around the GTA; online meetings run on Zoom. Newcomers are always welcome.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n</div>\n<!-- /wp:accordion -->', 'Questions & answers', 'Answers from people who\'ve been exactly where you are. Don\'t see your question? Get in touch.', 'publish', 'closed', 'closed', '', 'faq', '', '', '2026-09-06 15:48:46', '2026-09-06 19:48:46', '', 0, 'http://localhost:8888/matoronto/faq/', 0, 'page', '', 0),
(59, 0, '2026-09-06 15:20:02', '2026-09-06 19:20:02', '<!-- wp:accordion {\"autoclose\":true,\"headingLevel\":3,\"className\":\"ma-faq\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\"}}} -->\n<div class=\"wp-block-accordion ma-faq\">\n	<!-- wp:accordion-item {\"openByDefault\":true} -->\n	<div class=\"wp-block-accordion-item is-open\">\n		<!-- wp:accordion-heading {\"level\":3} -->\n		<h3 class=\"wp-block-accordion-heading\"><button class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">What is Marijuana Anonymous?</span><span class=\"wp-block-accordion-heading__toggle-icon\"></span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">MA is a fellowship of people who share their experience, strength, and hope with each other so they may solve their common problem and help others recover from marijuana addiction. We use the same Twelve Steps of recovery founded by Alcoholics Anonymous.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item  -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading {\"level\":3} -->\n		<h3 class=\"wp-block-accordion-heading\"><button class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">How much does it cost?</span><span class=\"wp-block-accordion-heading__toggle-icon\"></span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">Nothing. There are no dues or fees for membership. MA is entirely self-supporting through voluntary contributions from members — the 7th Tradition.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item  -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading {\"level\":3} -->\n		<h3 class=\"wp-block-accordion-heading\"><button class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">Do I have to speak or share personal details?</span><span class=\"wp-block-accordion-heading__toggle-icon\"></span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">No. You can come to a meeting and simply listen for as long as you like. Many people attend several meetings before sharing anything. Only your first name is ever needed — anonymity is a core principle.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item  -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading {\"level\":3} -->\n		<h3 class=\"wp-block-accordion-heading\"><button class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">How do I know if I am a marijuana addict?</span><span class=\"wp-block-accordion-heading__toggle-icon\"></span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">Only you can decide. Many members found it helpful to read The Twelve Questions — an honest self-inventory about how marijuana affects your life. If marijuana is causing problems and you cannot seem to stop, MA may be for you.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item  -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading {\"level\":3} -->\n		<h3 class=\"wp-block-accordion-heading\"><button class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">Is MA religious?</span><span class=\"wp-block-accordion-heading__toggle-icon\"></span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">No. MA is not affiliated with any religious or secular organization. The program refers to a higher power of your own understanding — that can be anything, including the group itself. Members hold every belief and none.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n	<!-- wp:accordion-item  -->\n	<div class=\"wp-block-accordion-item\">\n		<!-- wp:accordion-heading {\"level\":3} -->\n		<h3 class=\"wp-block-accordion-heading\"><button class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-title\">What happens at a meeting?</span><span class=\"wp-block-accordion-heading__toggle-icon\"></span></button></h3>\n		<!-- /wp:accordion-heading -->\n\n		<!-- wp:accordion-panel -->\n		<div class=\"wp-block-accordion-panel\">\n			<!-- wp:paragraph {\"className\":\"ma-faq__answer\",\"textColor\":\"muted\",\"fontSize\":\"medium\"} -->\n			<p class=\"ma-faq__answer has-muted-color has-text-color has-medium-font-size\">Meetings usually open with a reading, followed by members sharing their experience on a topic or a Step. They typically last about an hour. In-person meetings are held around the GTA; online meetings run on Zoom. Newcomers are always welcome.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:accordion-panel -->\n	</div>\n	<!-- /wp:accordion-item -->\n</div>\n<!-- /wp:accordion -->', 'FAQ', 'Answers from people who\'ve been exactly where you are. Don\'t see your question? Get in touch.', 'inherit', 'closed', 'closed', '', '58-revision-v1', '', '', '2026-09-06 15:20:02', '2026-09-06 19:20:02', '', 58, 'http://localhost:8888/matoronto/?p=59', 0, 'revision', '', 0);
