className\":\"ma-lit-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-lit-card__desc has-muted-color has-text-color has-small-font-size\">A gentle introduction to your first meetings — what happens, what to expect, and why you are welcome.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-lit-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-lit-card__cta has-x-small-font-size\">Read online <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:group {\"className\":\"ma-lit-card\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group ma-lit-card\">\n		<!-- wp:group {\"className\":\"ma-lit-card__cover\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-lit-card__cover\">\n			<!-- wp:paragraph {\"className\":\"ma-lit-card__kind\"} -->\n			<p class=\"ma-lit-card__kind\">Booklet</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"ma-lit-card__cover-title\"} -->\n			<p class=\"ma-lit-card__cover-title\">Twelve Steps Workbook</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"ma-lit-card__body\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-lit-card__body\">\n			<!-- wp:heading {\"level\":3,\"className\":\"ma-lit-card__title\",\"fontSize\":\"large\"} -->\n			<h3 class=\"wp-block-heading ma-lit-card__title has-large-font-size\"><a href=\"#\">Twelve Steps Workbook</a></h3>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"ma-lit-card__desc\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"ma-lit-card__desc has-muted-color has-text-color has-small-font-size\">Guided questions for working each of the Twelve Steps, on your own or with a sponsor.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:paragraph {\"className\":\"is-style-arrow-link ma-lit-card__cta\",\"fontSize\":\"x-small\"} -->\n			<p class=\"is-style-arrow-link ma-lit-card__cta has-x-small-font-size\">Learn more <span aria-hidden=\"true\">&rarr;</span></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"align\":\"full\",\"className\":\"ma-lit__note\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n<p class=\"alignfull ma-lit__note has-muted-color has-text-color has-small-font-size\">All proceeds from MA literature support the fellowship&#039;s primary purpose.</p>\n<!-- /wp:paragraph -->', 'Reading for recovery', 'Official Marijuana Anonymous literature — books, pamphlets, and daily readings. Available through MA World Services; many pieces are free to read online.', 'inherit', 'closed', 'closed', '', '63-revision-v1', '', '', '2026-09-06 15:56:15', '2026-09-06 19:56:15', '', 63, 'http://localhost:8888/matoronto/?p=65', 0, 'revision', '', 0),
(66, 0, '2026-09-06 16:12:47', '2026-09-06 20:12:47', '<div class=\"ma-form__row\">\n	<label class=\"ma-form__field\">\n		<span class=\"ma-form__label\">Name</span>\n		[text* your-name placeholder \"First name (or initials)\"]\n	</label>\n	<label class=\"ma-form__field\">\n		<span class=\"ma-form__label\">Email</span>\n		[email* your-email placeholder \"you@example.com\"]\n	</label>\n</div>\n<label class=\"ma-form__field\">\n	<span class=\"ma-form__label\">Subject</span>\n	[text your-subject placeholder \"How can we help?\"]\n</label>\n<label class=\"ma-form__field ma-form__field--message\">\n	<span class=\"ma-form__label\">Message</span>\n	[textarea* your-message rows:6 placeholder \"Tell us a little about what is going on. There is no wrong way to start.\"]\n</label>\n[submit class:ma-form__submit \"Send message\"]\n[MA Toronto] [your-subject]\nMA Toronto <wordpress@localhost>\ninfo@matoronto.org\nFrom: [your-name] <[your-email]>\nSubject: [your-subject]\n\n[your-message]\n\n-- \nSent from the contact form on http://localhost:8888/matoronto\nReply-To: [your-email]\n\n0\n0\n\n[_site_title] \"[your-subject]\"\n[_site_title] <info@matoronto.org>\nMessage Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\n[your-email]\nReply-To: [_site_admin_email]\n\n0\n0\nThank you. A member will get back to you soon.\nThere was an error trying to send your message. Please try again later.\nOne or more fields have an error. Please check and try again.\nThere was an error trying to send your message. Please try again later.\nYou must accept the terms and conditions before sending your message.\nPlease fill out this field.\nThis field has a too long input.\nThis field has a too short input.\nThere was an unknown error uploading the file.\nYou are not allowed to upload files of this type.\nThe uploaded file is too large.\nThere was an error uploading the file.\nPlease enter a date in YYYY-MM-DD format.\nThis field has a too early date.\nThis field has a too late date.\nPlease enter a number.\nThis field has a too small number.\nThis field has a too large number.\nThe answer to the quiz is incorrect.\nYour entered code is incorrect.\nPlease enter an email address.\nPlease enter a URL.\nPlease enter a telephone number.', 'MA Toronto — Contact', '', 'publish', 'closed', 'closed', '', 'ma-toronto-contact', '', '', '2026-09-06 16:12:47', '2026-09-06 20:12:47', '', 0, 'http://localhost:8888/matoronto/?post_type=wpcf7_contact_form&p=66', 0, 'wpcf7_contact_form', '', 0),
(67, 0, '2026-09-06 16:14:04', '2026-09-06 20:14:04', '<!-- wp:group {\"templateLock\":\"contentOnly\",\"align\":\"full\",\"className\":\"ma-contact\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|90\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull ma-contact\">\n\n	<!-- wp:group {\"className\":\"ma-contact__aside\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group ma-contact__aside\">\n\n		<!-- wp:paragraph {\"className\":\"ma-contact__intro\",\"textColor\":\"body\",\"fontSize\":\"medium\"} -->\n		<p class=\"ma-contact__intro has-body-color has-text-color has-medium-font-size\">Questions about meetings, the program, or getting started? Reach out. A member will get back to you — everything you share is kept confidential.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:group {\"className\":\"ma-contact__links\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group ma-contact__links\">\n\n			<!-- wp:group {\"className\":\"ma-contact__card\",\"layout\":{\"type\":\"default\"}} -->\n			<div class=\"wp-block-group ma-contact__card\">\n				<!-- wp:paragraph {\"className\":\"ma-contact__icon ma-contact__icon--mail\"} -->\n				<p class=\"ma-contact__icon ma-contact__icon--mail\">&#9993;</p>\n				<!-- /wp:paragraph -->\n\n				<!-- wp:group {\"className\":\"ma-contact__card-text\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group ma-contact__card-text\">\n					<!-- wp:paragraph {\"className\":\"ma-contact__card-label\"} -->\n					<p class=\"ma-contact__card-label\">Email</p>\n					<!-- /wp:paragraph -->\n\n					<!-- wp:paragraph {\"className\":\"ma-contact__card-value\"} -->\n					<p class=\"ma-contact__card-value\"><a href=\"mailto:info@matoronto.org\">info@matoronto.org</a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:group -->\n\n			<!-- wp:group {\"className\":\"ma-contact__card\",\"layout\":{\"type\":\"default\"}} -->\n			<div class=\"wp-block-group ma-contact__card\">\n				<!-- wp:paragraph {\"className\":\"ma-contact__icon ma-contact__icon--clock\"} -->\n				<p class=\"ma-contact__icon ma-contact__icon--clock\">&#9200;</p>\n				<!-- /wp:paragraph -->\n\n				<!-- wp:group {\"className\":\"ma-contact__card-text\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group ma-contact__card-text\">\n					<!-- wp:paragraph {\"className\":\"ma-contact__card-label\"} -->\n					<p class=\"ma-contact__card-label\">Prefer to just show up?</p>\n					<!-- /wp:paragraph -->\n\n					<!-- wp:paragraph {\"className\":\"ma-contact__card-value\"} -->\n					<p class=\"ma-contact__card-value\"><a href=\"http://localhost:8888/matoronto/meetings/\">See the meeting schedule <span aria-hidden=\"true\">&rarr;</span></a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:group -->\n\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:paragraph {\"className\":\"ma-contact__crisis\",\"textColor\":\"muted\",\"fontSize\":\"small\"} -->\n		<p class=\"ma-contact__crisis has-muted-color has-text-color has-small-font-size\">If you are in crisis or need immediate help, please call or text 988 (Suicide Crisis Helpline) or 911. MA is a peer-support fellowship, not an emergency service.</p>\n		<!-- /wp:paragraph -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"ma-contact__form\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group ma-contact__form\">\n		<!-- wp:shortcode -->\n		[contact-form-7 id=\"6e3a479\" title=\"MA Toronto — Contact\"]\n		<!-- /wp:shortcode -->\n\n		<!-- wp:paragraph {\"className\":\"ma-contact__note\",\"textColor\":\"muted\",\"fontSize\":\"xx-small\"} -->\n		<p class=\"ma-contact__note has-muted-color has-text-color has-xx-small-font-size\">We typically reply within a day or two. Your details are never shared.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->', 'You are no longer alone.', '', 'publish', 'closed', 'closed', '', 'contact', '', '', '2026-09-06 16:14:04', '2026-09-06 20:14:04', '', 0, 'http://localhost:8888/matoronto/contact/', 0, 'page', '', 0),
